<?php
/** Proof — reply, confirm, reopen (spec "Proof", 3): a reply on a pending ticket reopens it and tells the assignee; confirm → solved resolved via requester with actor_requester_id; reopen within the window with the reason; after the window → the closed message and POST 422; a reply on a closed ticket → nothing written; the 31st POST in an hour → 429. */
require __DIR__ . '/lib.php';
$W = world();
marco_in_general();
$marco = as_member(27); $lena = as_member(28);
$v = visitor();
[$c, $b, $num] = file_request($v, 'acting@customer.invalid', 'SMOKE acting');
$t = ticket_by_number($num);
$token = mailed_token($t);
$rid = (int) ticket_row($t)['requester_id'];
echo "1. A reply on a pending ticket\n";
act($marco, '/tickets/assign.php', ['ticket' => $t, 'assignee' => 'me']);
act($marco, '/tickets/reply.php', ['ticket' => $t, 'body' => 'Try turning it off and on.', 'then_status' => 'pending']);
ok(ticket_status($t) === 'pending', 'support set it pending');
$since = last_activity_id();
$txt = need('HD_DEV_STATE') . '/reply.txt'; file_put_contents($txt, 'SMOKE reply file');
[$c, $b, $h, $loc] = public_post($v, '/t/' . $token . '/reply', ['token' => $token, 'body' => 'Did that, still broken.'], [$txt]);
ok($c === 302 && $loc === '/t/' . $token . '?notice=replied', 'POST reply: back to the page with the notice');
$row = ticket_row($t);
ok(ticket_status($t) === 'open' && $row['last_requester_reply_at'] !== null, 'the trigger reopened it: open, last_requester_reply_at set');
$m = q("SELECT kind, channel, author_requester_id FROM messages WHERE ticket_id = :t ORDER BY id DESC LIMIT 1", ['t' => $t])[0];
ok($m['kind'] === 'public_reply' && $m['channel'] === 'portal' && (int) $m['author_requester_id'] === $rid && (int) one('SELECT count(*) FROM attachments WHERE ticket_id = :t AND uploaded_by_requester_id = :r', ['t' => $t, 'r' => $rid]) === 1, 'a public reply on the portal channel by the requester, with its file');
$ob = outbox($t, 'replied');
ok(count(array_filter($ob, fn ($o) => (int) $o['member_id'] === 27 && str_contains($o['body'], 'still broken'))) === 1, 'the assignee\'s replied notice');
$l = array_values(array_filter(activity('ticket.reply', $since), fn ($r) => (int) $r['ticket_id'] === $t));
ok(count($l) === 1 && (int) $l[0]['actor_requester_id'] === $rid && $l[0]['actor_member_id'] === null && $l[0]['source'] === 'portal' && json_decode($l[0]['after'], true)['channel'] === 'portal', 'ticket.reply logged with actor_requester_id and channel portal');
$body = req('GET', '/t/' . $token . '?notice=replied', ['jar' => $v])['body'];
ok(str_contains($body, 'id="public-notice"') && str_contains($body, 'Sent — we have it.') && str_contains($body, 'Did that, still broken.') && str_contains($body, '<span class="fw-semibold">You</span>'), 'the page shows the notice and the reply as "You"');
echo "2. Confirm\n";
act($marco, '/tickets/reply.php', ['ticket' => $t, 'body' => 'Replaced the cable.']);
$body = secure_page($v, $token)['body'];
ok(str_contains($body, 'id="public-confirm-btn"') && str_contains($body, 'Did this resolve it?'), 'after a reply from us: "Did this resolve it?"');
$since = last_activity_id();
[$c, $b, $h, $loc] = public_post($v, '/t/' . $token . '/confirm', ['token' => $token]);
ok($c === 302 && $loc === '/t/' . $token . '?notice=confirmed' && ticket_status($t) === 'solved' && ticket_row($t)['resolution_code'] === 'resolved', 'confirm: solved with resolved');
$tr = array_values(array_filter(activity('ticket.transition', $since), fn ($r) => (int) $r['ticket_id'] === $t));
$cf = array_values(array_filter(activity('ticket.confirm', $since), fn ($r) => (int) $r['ticket_id'] === $t));
ok(count($tr) === 1 && json_decode($tr[0]['after'], true)['via'] === 'requester' && (int) $tr[0]['actor_requester_id'] === $rid && $tr[0]['actor_member_id'] === null && count($cf) === 1 && (int) $cf[0]['actor_requester_id'] === $rid, 'ticket.confirm and ticket.transition (via requester) with actor_requester_id, no actor_member_id');
$body = secure_page($v, $token)['body'];
ok(str_contains($body, 'Solved — does this resolve it?') && str_contains($body, 'id="public-reopen-form"') && !str_contains($body, 'id="public-confirm-btn"'), 'the page: solved, the reopen box');
echo "3. Reopen\n";
$since = last_activity_id();
[$c, $b, $h, $loc] = public_post($v, '/t/' . $token . '/reopen', ['token' => $token, 'reason' => 'It broke again this morning.']);
ok($c === 302 && $loc === '/t/' . $token . '?notice=reopened' && ticket_status($t) === 'open' && (int) ticket_row($t)['reopen_count'] === 1, 'reopen within the window: open, reopen_count 1');
$m = q("SELECT kind, body_text FROM messages WHERE ticket_id = :t ORDER BY id DESC LIMIT 1", ['t' => $t])[0];
ok($m['kind'] === 'public_reply' && $m['body_text'] === 'It broke again this morning.' && count(array_filter(activity('ticket.reopen', $since), fn ($r) => (int) $r['ticket_id'] === $t)) === 1, 'the reason is a public reply; ticket.reopen logged');
act($marco, '/tickets/transition.php', ['ticket' => $t, 'status' => 'solved', 'resolution_code' => 'resolved']);
q("UPDATE tickets SET solved_at = now() - interval '20 days' WHERE id = :t", ['t' => $t]);
$body = secure_page($v, $token)['body'];
ok(str_contains($body, 'id="public-reopen-late"') && str_contains($body, 'This was closed on') && str_contains($body, 'href="/request"') && !str_contains($body, 'id="public-reopen-form"'), 'after the window: "This was closed on … Start a new request"');
[$c, $b] = public_post($v, '/t/' . $token . '/reopen', ['token' => $token, 'reason' => 'late']);
ok($c === 422 && ticket_status($t) === 'solved', 'POST reopen after the window: 422, still solved');
echo "4. Closed\n";
act($lena, '/tickets/close.php', ['ticket' => $t, 'resolution_code' => 'resolved']);
$n = (int) one('SELECT count(*) FROM messages WHERE ticket_id = :t', ['t' => $t]);
[$c, $b, $h, $loc] = public_post($v, '/t/' . $token . '/reply', ['token' => $token, 'body' => 'one more thing']);
ok($c === 302 && $loc === '/t/' . $token . '?notice=closed' && (int) one('SELECT count(*) FROM messages WHERE ticket_id = :t', ['t' => $t]) === $n, 'a reply on a closed ticket: the closed notice, nothing written');
$body = secure_page($v, $token)['body'];
ok(str_contains($body, 'id="public-closed"') && str_contains($body, 'Start a new request') && !str_contains($body, 'id="public-reply-form"') && str_contains($body, '>Closed<'), 'the page says it is closed and sends them to the form');
echo "5. The abuse guard\n";
$v2 = visitor();
[$c, $b, $num2] = file_request($v2, 'busy2@customer.invalid', 'SMOKE busy link');
$t2 = ticket_by_number($num2); $tok2 = mailed_token($t2);
$codes = [];
for ($i = 1; $i <= 31; $i++) { [$c] = public_post($v2, '/t/' . $tok2 . '/reply', ['token' => $tok2, 'body' => 'spam ' . $i]); $codes[] = $c; }
ok(count(array_filter(array_slice($codes, 0, 30), fn ($c) => $c === 302)) === 30 && $codes[30] === 429, 'thirty replies in an hour pass; the 31st: 429');
ok((int) one('SELECT count(*) FROM messages WHERE ticket_id = :t', ['t' => $t2]) === 31, 'thirty written (plus the first message), the 31st not');
finish();
